import {esc} from './ui.js?v=187';
export const CELL_PROFILES=[
 {name:'JANUS',motto:'Tout a un prix. Rien ne porte notre nom.',description:'Des comptes aux cargaisons : JANUS donne une façade civile aux moyens de Fracture. Son identité repose sur la discrétion et les intermédiaires.'},
 {name:'PRISME',motto:'Ce que vous voyez a déjà été modifié.',description:'Systèmes autonomes et intrusions : PRISME brouille la frontière entre incident technique et attaque organisée. Ses membres privilégient la précision et les traces trompeuses.'},
 {name:'CENDRE',motto:'Quand l’ordre arrive, tout est déjà en place.',description:'Matériel et coordination de terrain : CENDRE transforme les instructions en opérations. Son identité repose sur le cloisonnement et la discipline.'},
 {name:'DIRECTION',motto:'Chaque cellule ne connaît qu’une partie du plan.',description:'Le commandement relie les opérations de Fracture sans se montrer. L’enquête doit établir qui donne les ordres et comment ils circulent.'}
];
export const SUSPECT_PROFILES={
 s0:{trait:'La négociatrice',bio:'Vesper parle bas, laisse ses interlocuteurs annoncer leur prix et ne promet jamais deux fois. Pour elle, la fidélité est une dette dont on conserve la trace.',signature:'Ne signe rien de sa main ; préfère les chaînes de sociétés écrans.'},
 s1:{trait:'Le convoyeur',bio:'Cobalt retient les horaires, les visages et les sorties. Pragmatique, il fait davantage confiance à une livraison ponctuelle qu’à un discours sur la cause.',signature:'Fait passer les cargaisons sensibles au milieu de flux ordinaires.'},
 s2:{trait:'La perfectionniste',bio:'Mantis voit le monde comme un système à corriger. Peu démonstrative, elle supporte mal l’improvisation et traite chaque échec comme une anomalie à comprendre.',signature:'Privilégie les systèmes autonomes et les signatures de commande discrètes.'},
 s3:{trait:'L’insaisissable',bio:'Relay change de ton aussi vite que de canal. Brillant, impatient et ironique, il recherche la porte oubliée plutôt que l’affrontement direct.',signature:'Exploite les accès de maintenance et les habitudes des administrateurs.'},
 s4:{trait:'La voix du terrain',bio:'Orphée sait donner un ordre sans hausser la voix. Elle inspire la loyauté par sa présence, mais ne confie à chacun que le strict nécessaire.',signature:'Coordonne des équipes cloisonnées par des messages courts.'},
 s5:{trait:'Le courtier',bio:'Kestrel se fond dans une salle de transit comme dans un bureau d’achats. Patient et méthodique, il connaît la valeur de chaque pièce et de chaque silence.',signature:'Fractionne les achats et détourne des composants à double usage.'},
 s7:{trait:'La négociatrice de l’ombre',bio:'Sable obtient des accords que personne ne souhaite voir consignés. Derrière ses manières impeccables, elle retient les dettes et les faiblesses de chaque interlocuteur.',signature:'Fait passer les paiements clandestins pour des honoraires de conseil.'},
 s8:{trait:'Le passeur',bio:'Rook connaît les frontières par leurs angles morts. Il parle peu, respecte ses horaires et refuse les cargaisons dont il ne contrôle pas lui-même le trajet.',signature:'Change de véhicule et de documents à chaque étape du transport.'},
 s9:{trait:'La voix invisible',bio:'Nyx construit des réseaux qui ne restent jamais en place. Méfiante et précise, elle coupe un canal dès qu’un détail lui semble trop prévisible.',signature:'Fragmente les messages entre plusieurs relais anonymes.'},
 s10:{trait:'Le financier',bio:'Silas donne aux opérations les plus troubles l’apparence d’une gestion ordinaire. Patient, cultivé et méticuleux, il préfère une écriture comptable à une menace.',signature:'Dissimule les transferts derrière des fonds et des participations croisées.'},
 s11:{trait:'La logisticienne',bio:'Vega sait trouver un véhicule, un dépôt et une sortie quand les plans s’effondrent. Elle fait confiance aux personnes qui tiennent leurs engagements sur le terrain.',signature:'Multiplie les dépôts temporaires et les itinéraires de repli.'},
 s12:{trait:'Le voleur d’archives',bio:'Onyx fréquente les lieux où l’information vaut plus que les objets exposés. Observateur et réservé, il laisse ses clients ignorer comment il obtient ce qu’ils achètent.',signature:'Revend des données sensibles par des intermédiaires sans contact direct.'},
 s6:{trait:'Le stratège',bio:'L’Architecte laisse les autres occuper le devant de la scène. Il raisonne en dépendances, en délais et en leviers ; la distance est sa première protection.',signature:'Relie les cellules par des intermédiaires et des instructions compartimentées.'}
};
export const identityKnown=t=>!!(t.identified||t.arrested);
export function suspectPortrait(t,extra=''){if(!identityKnown(t))return `<div class="suspect-portrait unknown-portrait ${extra}" role="img" aria-label="Portrait non disponible"><span aria-hidden="true">?</span><small>PORTRAIT NON DISPONIBLE</small></div>`;return `<img class="suspect-portrait ${extra}" src="./assets/fracture/${t.templateId??t.id}.png" alt="Portrait de ${esc(t.name)}" width="384" height="480" loading="lazy">`;}
export function discoveryMarkup(t){return `<div class="dossier-origin"><span class="eyebrow">ORIGINE DU DOSSIER${t.discovery?' · TOUR '+t.discovery.turn:''}</span><p>${esc(t.discovery?.source||'Dossier déjà connu. Son origine n’a pas été consignée dans cette sauvegarde.')}</p></div>`;}
export function suspectProfile(t){const p=SUSPECT_PROFILES[t.templateId??t.id],c=CELL_PROFILES[t.cell];return `<section class="suspect-profile">${suspectPortrait(t)}<div><span class="eyebrow">${identityKnown(t)?esc(p.trait):'Identité à confirmer'}</span><p>${identityKnown(t)?esc(p.bio):'Ce nom de code désigne une piste. Le portrait apparaîtra au fil de l’enquête.'}</p>${identityKnown(t)?`<p class="muted">${esc(p.signature)}</p>`:''}</div></section><section class="cell-profile"><strong>${c.name} · « ${esc(c.motto)} »</strong><p>${esc(c.description)}</p></section>${discoveryMarkup(t)}`;}
